<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { t, locale } from '../i18n'
import { governance, isOwner, saveUser, resolveReview, governanceError, type AdminUser, type Review } from '../governance'
import { state, saveSlot } from '../operations'
import { useArticles } from '../store'
defineProps<{tab:string}>()
const { articles, save, remove }=useArticles()
const notice=ref(''), status=ref('all'), editing=ref(false)
const form=reactive<AdminUser>({id:'',name:'',email:'',role:'editor',active:true})
const search=ref(''),selected=ref('')
const selectedReview=computed(()=>governance.reviews.find(r=>r.id===selected.value))
const reviewLabel=(status:string)=>t(({pending:'در انتظار بررسی',approved:'تأییدشده',rejected:'ردشده'} as Record<string,string>)[status]||status)
const reviews=computed(()=>governance.reviews.filter(r=>(status.value==='all'||r.status===status.value)&&(r.title+' '+(governance.users.find(u=>u.id===r.author)?.name||'')).includes(search.value.trim())))
function edit(user?:AdminUser){Object.assign(form,user||{id:crypto.randomUUID(),name:'',email:'',role:'editor',active:true});editing.value=true;notice.value=''}
function persist(){try{saveUser({...form});editing.value=false;notice.value=t('کاربر ذخیره شد','User saved')}catch(e){notice.value=(e as Error).message}}
const original=(r:Review)=>r.kind.startsWith('article')?articles.value.find(a=>a.id===r.target):r.kind==='doctor'?state.doctors.find(d=>d.id===r.target):r.kind==='ticket'?state.tickets.find(s=>s.id===r.target):r.kind==='booking'?state.bookings.find(s=>s.id===r.target):state.slots.find(s=>s.id===r.target)
function review(r:Review,approve:boolean){try{resolveReview(r,approve,original(r),()=>{if(r.kind==='article')save(r.payload);else if(r.kind==='article-delete')remove(r.target);else if(r.kind==='slot')saveSlot(r.payload);else if(r.kind==='ticket')Object.assign(state.tickets.find(s=>s.id===r.target)!,r.payload);else if(r.kind==='booking')Object.assign(state.bookings.find(s=>s.id===r.target)!,r.payload);else {const i=state.doctors.findIndex(d=>d.id===r.target);if(i<0)state.doctors.push({...r.payload});else state.doctors[i]={...r.payload}}});notice.value=t(approve?'تغییر تأیید و اعمال شد':'درخواست رد شد',approve?'Change approved and applied':'Change rejected')}catch(e){notice.value=(e as Error).message}}
const fields:Record<string,string>={title:'عنوان',excerpt:'خلاصه',body:'متن',status:'وضعیت',name:'نام',specialty:'تخصص',bio:'معرفی',active:'فعال',date:'تاریخ',time:'زمان',price:'هزینه',duration:'مدت',blocked:'مسدود',photo:'عکس',reply:'پاسخ',message:'پیام',category:'دسته‌بندی'}
function changes(r:Review){const before=JSON.parse(r.before)||{};const after=r.payload||{};return Object.keys(fields).filter(k=>JSON.stringify(before[k])!==JSON.stringify(after[k])).map(k=>({label:fields[k],before:String(before[k]??'—'),after:String(after[k]??'—')}))}
</script>
<template>
<section class="ops-panel governance-panel">
 <template v-if="tab==='users'">
  <div class="ops-panel-title"><h2>{{t('کاربران و دسترسی‌ها','Users and roles')}}</h2><button v-if="isOwner" class="button button-primary" @click="edit()">{{t('افزودن کاربر','Add user')}}</button></div>
  <div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>{{t('نام','Name')}}</th><th>{{t('ایمیل','Email')}}</th><th>{{t('نقش','Role')}}</th><th>{{t('وضعیت','Status')}}</th><th></th></tr></thead><tbody><tr v-for="user in governance.users" :key="user.id"><td>{{user.name}}</td><td dir="ltr">{{user.email}}</td><td>{{user.role==='owner'?t('مدیر اصلی','Owner'):t('ویرایشگر','Editor')}}</td><td>{{user.active?t('فعال','Active'):t('غیرفعال','Inactive')}}</td><td><button v-if="isOwner" class="button button-ghost" @click="edit(user)">{{t('ویرایش','Edit')}}</button></td></tr></tbody></table></div>
  <form v-if="editing&&isOwner" class="governance-form" @submit.prevent="persist"><div class="form-grid"><label>{{t('نام','Name')}}<input v-model.trim="form.name" required/></label><label>{{t('ایمیل','Email')}}<input v-model.trim="form.email" required type="email"/></label><label>{{t('نقش','Role')}}<select v-model="form.role"><option value="editor">{{t('ویرایشگر','Editor')}}</option><option value="owner">{{t('مدیر اصلی','Owner')}}</option></select></label><label>{{t('وضعیت','Status')}}<select v-model="form.active"><option :value="true">{{t('فعال','Active')}}</option><option :value="false">{{t('غیرفعال','Inactive')}}</option></select></label></div><button class="button button-primary">{{t('ذخیره کاربر','Save user')}}</button><button type="button" class="button button-ghost" @click="editing=false">{{t('انصراف','Cancel')}}</button></form>
 </template>
 <template v-else>
  <div class="admin-stats review-stats"><button @click="status='all'"><span>{{t('همه درخواست‌ها','All requests')}}</span><strong>{{governance.reviews.length.toLocaleString(locale())}}</strong></button><button @click="status='pending'"><span>{{t('در انتظار بررسی','Awaiting review')}}</span><strong>{{governance.reviews.filter(r=>r.status==='pending').length.toLocaleString(locale())}}</strong></button><button @click="status='approved'"><span>{{t('تأییدشده','Approved')}}</span><strong>{{governance.reviews.filter(r=>r.status==='approved').length.toLocaleString(locale())}}</strong></button><button @click="status='rejected'"><span>{{t('ردشده','Rejected')}}</span><strong>{{governance.reviews.filter(r=>r.status==='rejected').length.toLocaleString(locale())}}</strong></button></div>
  <div class="ops-panel-title"><h2>{{t('تاریخچه اصلاحات','Change history')}}</h2><div class="admin-filters"><input v-model="search" type="search" :placeholder="t('جست‌وجوی درخواست','Search requests')" :aria-label="t('جست‌وجوی درخواست','Search requests')"/><select v-model="status" :aria-label="t('وضعیت درخواست','Request status')"><option value="all">{{t('همه','All')}}</option><option value="pending">{{t('در انتظار','Pending')}}</option><option value="approved">{{t('تأییدشده','Approved')}}</option><option value="rejected">{{t('ردشده','Rejected')}}</option></select></div></div>
  <div class="admin-table-wrap"><table class="admin-table approval-table"><thead><tr><th>{{t('درخواست','Request')}}</th><th>{{t('ارسال‌کننده','Submitted by')}}</th><th>{{t('تاریخ ثبت','Submitted')}}</th><th>{{t('وضعیت','Status')}}</th><th>{{t('تاریخ بررسی','Reviewed')}}</th><th>{{t('عملیات','Actions')}}</th></tr></thead><tbody><tr v-for="r in reviews" :key="r.id"><td class="wrap-cell"><strong>{{r.title}}</strong><small v-if="r.sample" class="sample-badge">{{t('نمونه','Sample')}}</small></td><td>{{governance.users.find(u=>u.id===r.author)?.name||'—'}}</td><td>{{new Date(r.created).toLocaleDateString(locale())}}</td><td><span :class="['status-pill',r.status]">{{reviewLabel(r.status)}}</span></td><td>{{r.reviewedAt?new Date(r.reviewedAt).toLocaleDateString(locale()):'—'}}</td><td><button class="button button-ghost" @click="selected=selected===r.id?'':r.id">{{t(r.status==='pending'?'بررسی درخواست':'مشاهده جزئیات',r.status==='pending'?'Review request':'View details')}}</button></td></tr></tbody></table><p v-if="!reviews.length" class="empty-state">{{t('درخواستی در این وضعیت وجود ندارد','No matching requests')}}</p></div>
  <article v-if="selectedReview" class="review-card"><header><h3>{{selectedReview.title}}</h3><button class="button button-ghost" @click="selected=''">{{t('بستن جزئیات','Close details')}}</button></header><p v-if="selectedReview.kind==='article-delete'">{{t('درخواست حذف مقاله','Article deletion requested')}}</p><div v-for="change in changes(selectedReview)" :key="change.label" class="review-diff"><b>{{t(change.label)}}</b><div><small>{{t('فعلی','Current')}}</small><pre>{{change.before}}</pre></div><div><small>{{t('پیشنهادی','Proposed')}}</small><pre>{{change.after}}</pre></div></div><p v-if="selectedReview.note">{{selectedReview.note}}</p><div v-if="selectedReview.status==='pending'&&isOwner" class="review-actions"><button class="button button-primary" @click="review(selectedReview,true)">{{t('تأیید و اعمال','Approve and apply')}}</button><button class="button button-ghost" @click="review(selectedReview,false)">{{t('رد درخواست','Reject')}}</button></div></article>
 </template>
 <p role="status">{{notice||governanceError}}</p>
</section>
</template>
